import numpy as np
t=df['t']; P=df['P']; y=df['dP_dt']
one=np.ones_like(P)
def build(w):
    return np.column_stack([one/P,t/P,np.sin(w*t)/P,np.cos(w*t)/P,np.sin(2*w*t)/P,np.cos(2*w*t)/P,P*np.log(P),one,t,P])
best=None
for w in np.linspace(0.05,0.1,5001):
    X=build(w)
    c,_,_,_=np.linalg.lstsq(X,y,rcond=None)
    e=np.mean((X@c-y)**2)/np.var(y)
    if best is None or e<best[0]: best=(e,w,c)
print(best[0],best[1]); print(np.round(best[2],6))

import numpy as np
t=df['t']; P=df['P']; y=df['dP_dt']
one=np.ones_like(P)
base=[t,P*np.log(P),one,P]
forms={'1':one,'P':P,'1/P':one/P,'P2':P**2}
for name,f in forms.items():
    best=(9,0)
    for w in np.linspace(0.05,2.0,1950):
        X=np.column_stack(base+[f*np.sin(w*t),f*np.cos(w*t)])
        c,_,_,_=np.linalg.lstsq(X,y,rcond=None)
        e=np.mean((X@c-y)**2)/np.var(y)
        if e<best[0]: best=(e,w)
    print(name,best)
